import {icon} from "./icons.js";
import {escapeHtml as esc} from "../account.js";
import {documentUrl, fileSize, pendingProposals} from "../documents.js";
import {eventCount, eventTime} from "../events.js";
import {fullDate, parseDate} from "../date.js";
import {recurrenceLabel} from "../recurrence.js";

const plural = count => `${count} document${count > 1 ? "s" : ""}`;
const searchText = value => value.toLocaleLowerCase("fr-CA").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const importedDate = value => new Intl.DateTimeFormat("fr-CA", {day: "numeric", month: "short", timeZone: "America/Toronto"}).format(new Date(value));
export function documentBadge(document, events) {
  if (document.analysisState === "analysing") return '<span class="document-badge is-working"><span class="document-spinner"></span>Analyse en cours</span>';
  if (document.analysisState === "error") return '<span class="document-badge is-error">Analyse à réessayer</span>';
  if (document.analysisState === "pending") return '<span class="document-badge">PDF enregistré</span>';
  const pending = pendingProposals(document, events).length;
  return `<span class="document-badge ${pending ? "has-proposals" : "is-done"}">${pending ? `${pending} à vérifier` : document.proposals.length ? `${icon("check")}Ajoutés au calendrier` : "Aucun événement détecté"}</span>`;
}
function inspector(document, state) {
  if (!document) return `<aside class="document-inspector inspector-empty"><span class="inspector-placeholder">${icon("document")}</span><h2>Un PDF, tous ses détails.</h2><p>Sélectionne un document pour le consulter et retrouver ses événements.</p></aside>`;
  const pending = pendingProposals(document, state.events);
  const linked = state.events.filter(event => event.source?.documentId === document.id);
  return `<aside class="document-inspector" aria-label="Détails de ${esc(document.name)}"><button class="inspector-back" data-action="document-back">${icon("chevronLeft")}Tous les documents</button><div class="inspector-heading"><span class="home-eyebrow">APERÇU DU DOCUMENT</span><button class="icon-button" data-action="document-delete" data-document-id="${document.id}" aria-label="Supprimer ${esc(document.name)}">${icon("trash")}</button></div>
    <div class="pdf-preview" data-pdf-preview="${document.id}"><div class="pdf-preview-loading"><span class="document-spinner"></span>Préparation de l’aperçu…</div><a href="${documentUrl(document.id)}" target="_blank" rel="noopener">Ouvrir le PDF ${icon("external")}</a></div>
    <h2 class="inspector-name">${esc(document.name)}</h2><p class="document-meta">PDF <span>·</span> ${fileSize(document.size)} <span>·</span> Ajouté le ${esc(importedDate(document.createdAt))}</p>
    ${document.summary ? `<p class="document-summary">${esc(document.summary)}</p>` : ""}
    ${document.analysisError ? `<p class="document-analysis-error" role="status">${esc(document.analysisError)}</p>` : ""}
    <div class="inspector-events"><div class="inspector-section-heading">${icon("calendar")}<h3>Événements</h3><span>${linked.length}</span></div>
      ${pending.length ? `<p>${eventCount(pending.length)} à vérifier avant l’ajout.</p><button class="primary-button document-review-button" data-action="document-review" data-document-id="${document.id}">${icon("sparkles")}Vérifier les événements</button>` : document.analysisState === "ready" ? `<p>${linked.length ? "Le document reste lié à chaque événement." : "Aucun événement à ajouter. Ton PDF reste disponible ici."}</p>` : `<p>${document.analysisState === "analysing" ? "Gemini recherche les dates et les rendez-vous dans ce PDF." : "Recherche les dates et les rendez-vous avec Gemini."}</p><button class="secondary-button" data-action="document-analyze" data-document-id="${document.id}" ${state.documentJobs.some(job => job.documentId === document.id && ["uploading", "analysing", "waiting"].includes(job.status)) || !state.aiAvailable ? "disabled" : ""}>${icon("sparkles")}${document.analysisState === "pending" ? "Rechercher des événements" : "Réessayer l’analyse"}</button>${!state.aiAvailable ? '<p class="document-ai-note">La recherche sera disponible une fois Gemini configuré.</p>' : ""}`}
      ${linked.length ? `<div class="document-linked-events">${linked.map(event => `<button data-action="open-event" data-event-id="${event.id}"><span>${esc(fullDate(parseDate(event.date), false))}</span><strong>${esc(event.title)}</strong>${icon("chevronRight")}</button>`).join("")}</div>` : ""}
    </div><a class="document-download" href="${documentUrl(document.id, null, true)}">${icon("download")}Télécharger l’original</a></aside>`;
}
export function renderDocuments(state) {
  const query = searchText(state.documentQuery.trim());
  const filtered = state.documents.filter(document => (!query || searchText(`${document.name} ${document.summary}`).includes(query)) && (state.documentFilter === "all" || pendingProposals(document, state.events).length));
  const selected = state.documents.find(document => document.id === state.selectedDocumentId) || null;
  const pending = state.documents.filter(document => pendingProposals(document, state.events).length).length;
  const jobs = state.documentJobs;
  return `<section class="documents-page" aria-labelledby="documents-title"><header class="documents-intro"><div><p class="home-eyebrow">TES PDF ET LES MOMENTS QUI COMPTENT</p><h1 id="documents-title" tabindex="-1">Documents</h1><p>Un horaire, une invitation, un itinéraire. Garde le document, prévois la suite.</p></div><button class="primary-button document-add-button" data-action="document-add">${icon("plus")}Ajouter des PDF</button></header>
    ${jobs.length ? `<section class="document-import-jobs" aria-label="Imports de documents" aria-live="polite"><div class="import-jobs-heading"><strong>Import des documents</strong>${jobs.every(job => ["done", "error"].includes(job.status)) ? '<button data-action="document-jobs-dismiss" aria-label="Masquer les imports terminés">Fermer</button>' : '<span>Tu peux continuer à utiliser Tempo</span>'}</div>${jobs.map(job => `<div class="import-job"><span class="${["waiting", "uploading", "analysing"].includes(job.status) ? "document-spinner" : "import-job-symbol"}">${job.status === "done" ? icon("check") : job.status === "error" ? "!" : ""}</span><span><strong>${esc(job.name)}</strong><span>${esc(job.message || ({waiting: "En attente", uploading: "Enregistrement du PDF…", analysing: "PDF enregistré · recherche des événements…", done: "PDF enregistré"})[job.status])}</span></span>${job.status === "error" && job.retryable ? `<button data-action="document-job-retry" data-job-id="${job.id}">Réessayer</button>` : ""}</div>`).join("")}</section>` : ""}
    ${state.documentsStatus === "error" ? `<div class="documents-load-error" role="alert"><span>${esc(state.documentsError)}</span><button class="secondary-button" data-action="documents-retry">Réessayer</button></div>` : ""}
    ${state.documentsStatus === "loading" && !state.documents.length ? '<div class="documents-loading" role="status"><span class="document-spinner"></span>Chargement de tes documents…</div>' : state.documents.length ? `<div class="document-library-layout ${state.documentDetailsOpen ? "has-document-detail" : ""}"><section class="document-library" aria-label="Bibliothèque de PDF"><div class="document-library-toolbar"><div class="document-filters" role="group" aria-label="Filtrer les documents"><button data-action="document-filter-all" aria-pressed="${state.documentFilter === "all"}">Tous <span>${state.documents.length}</span></button><button data-action="document-filter-pending" aria-pressed="${state.documentFilter === "pending"}">À vérifier ${pending ? `<span>${pending}</span>` : ""}</button></div><label class="document-search">${icon("search")}<input id="document-search" type="search" placeholder="Rechercher" aria-label="Rechercher un document" value="${esc(state.documentQuery)}"/></label></div>
      <div class="document-list">${filtered.length ? filtered.map(document => `<button class="document-row ${selected?.id === document.id ? "is-selected" : ""}" data-action="document-select" data-document-id="${document.id}" aria-pressed="${selected?.id === document.id}"><span class="pdf-file-icon">${icon("document")}<span>PDF</span></span><span class="document-row-copy"><strong>${esc(document.name)}</strong><span class="document-meta">${fileSize(document.size)} <span>·</span> ${esc(importedDate(document.createdAt))}</span>${documentBadge(document, state.events)}</span>${icon("chevronRight", "document-row-arrow")}</button>`).join("") : `<div class="documents-no-results">${icon("search")}<h2>${query ? "Aucun document trouvé" : "Tout est à jour"}</h2><p>${query ? "Essaie un autre nom ou un mot du document." : "Aucun événement en attente de vérification."}</p></div>`}</div>
      <div class="document-dropzone compact" data-document-dropzone><span>${icon("upload")}Glisse d’autres PDF ici</span><button data-action="document-add">Parcourir les fichiers</button></div></section>${inspector(selected, state)}</div>` : state.documentsStatus !== "loading" ? `<div class="document-empty document-dropzone" data-document-dropzone><div class="document-empty-art"><span></span><span></span><div>${icon("document")}<strong>PDF</strong></div><i>${icon("sparkles")}</i></div><h2>Du document au calendrier.</h2><p>Dépose tes PDF ici. Gemini repère les événements,<br/>tu choisis ceux à ajouter.</p><button class="primary-button" data-action="document-add">${icon("upload")}Choisir des PDF</button><span class="document-drop-hint">ou glisse tes fichiers dans cette fenêtre</span><div class="document-empty-steps"><span><b>1</b>Garde tes PDF</span><span><b>2</b>Vérifie les dates</span><span><b>3</b>Ajoute les événements</span></div></div>` : ""}
    <footer class="documents-footnote"><span>${icon("document")}${plural(state.documents.length)} dans ta bibliothèque</span><span>PDF · 10 Mo par fichier <span>·</span> Analyse avec Gemini</span></footer><p class="document-privacy">Les PDF sont enregistrés dans ton compte HomeLab et transmis à Gemini lors de la recherche d’événements. Tu valides chaque ajout au calendrier.</p>
    <div class="document-drag-overlay" aria-hidden="true">${icon("upload")}Dépose tes PDF pour les ajouter</div></section>`;
}
function proposalRow(document, proposal, state) {
  const event = proposal.event;
  const added = state.events.some(event => event.source?.documentId === document.id && event.source.proposalId === proposal.id);
  const prefix = `proposal-${proposal.id}`;
  return `<article class="document-proposal ${added ? "is-added" : ""}" data-proposal-id="${proposal.id}" data-document-id="${document.id}"><div class="proposal-heading"><input id="${prefix}-select" type="checkbox" class="proposal-checkbox" aria-label="Ajouter ${esc(event.title)}" ${added ? "disabled" : "checked"}/><label for="${prefix}-select"><strong>${esc(event.title)}</strong><span>${esc(fullDate(parseDate(event.date)))}${event.endDate !== event.date ? ` → ${esc(fullDate(parseDate(event.endDate)))}` : ""} <span>·</span> ${esc(eventTime(event, state.preferences.timeFormat))}</span></label>${added ? `<span class="proposal-added">${icon("check")}Ajouté</span>` : ""}</div>
    <div class="proposal-source"><a href="${documentUrl(document.id, proposal.page)}" target="_blank" rel="noopener">${icon("document")}${proposal.page ? `Page ${proposal.page}` : "Voir le PDF"}${icon("external")}</a>${event.recurrence ? `<span>${esc(recurrenceLabel(event.recurrence))}</span>` : ""}</div>
    ${proposal.note ? `<p class="proposal-note">${esc(proposal.note)}</p>` : ""}
    ${added ? "" : `<details class="proposal-editor"><summary>Modifier les détails ${icon("edit")}</summary><div class="proposal-fields"><label for="${prefix}-title">Titre<input id="${prefix}-title" name="title" value="${esc(event.title)}" maxlength="160" required/></label><label class="proposal-all-day"><input name="allDay" type="checkbox" ${event.allDay ? "checked" : ""}/>Toute la journée</label><div class="proposal-date-fields"><label for="${prefix}-date">Date de début<input id="${prefix}-date" name="date" type="date" value="${event.date}" min="0001-01-01" max="9999-12-31" required/></label><label for="${prefix}-endDate">Date de fin<input id="${prefix}-endDate" name="endDate" type="date" value="${event.endDate}" min="${event.date}" max="9999-12-31" required/></label><label class="proposal-time" for="${prefix}-start" ${event.allDay ? "hidden" : ""}>Heure de début<input id="${prefix}-start" name="startTime" type="time" value="${event.startTime || "09:00"}" ${event.allDay ? "disabled" : "required"}/></label><label class="proposal-time" for="${prefix}-end" ${event.allDay ? "hidden" : ""}>Heure de fin<input id="${prefix}-end" name="endTime" type="time" value="${event.endTime || "10:00"}" ${event.allDay ? "disabled" : "required"}/></label></div><label for="${prefix}-description">Description<textarea id="${prefix}-description" name="description" rows="2" maxlength="4000">${esc(event.description)}</textarea></label>${event.recurrence ? '<p>Les changements s’appliqueront à toute la série. La répétition pourra être ajustée dans le calendrier.</p>' : ""}</div></details>`}</article>`;
}
export function reviewDocumentsDialog(documents, state) {
  const count = documents.reduce((count, document) => count + pendingProposals(document, state.events).length, 0);
  return `<dialog class="app-dialog document-review-dialog" aria-labelledby="document-review-title" aria-describedby="document-review-description"><form id="document-review-form" novalidate><header class="dialog-heading"><div><span class="event-dialog-eyebrow">${icon("sparkles")}REPÉRÉS DANS TES PDF</span><h2 id="document-review-title">Des moments à prévoir.</h2></div><button type="button" class="icon-button" data-action="document-dialog-close" aria-label="Fermer la revue">${icon("close")}</button></header><p class="dialog-description" id="document-review-description">${eventCount(count)} proposé${count > 1 ? "s" : ""}. Vérifie les dates et choisis ce qui rejoint ton calendrier.</p><div class="document-review-scroll"><div class="review-selection-toolbar"><label><input id="proposal-select-all" type="checkbox" checked/>Tout sélectionner</label><span>Heure de Toronto</span></div>${documents.map(document => `<section class="proposal-document-group"><header>${icon("document")}<h3>${esc(document.name)}</h3><a href="${documentUrl(document.id)}" target="_blank" rel="noopener" aria-label="Ouvrir ${esc(document.name)}">${icon("external")}</a></header>${document.summary ? `<p class="review-document-summary">${esc(document.summary)}</p>` : ""}${document.proposals.map(proposal => proposalRow(document, proposal, state)).join("")}</section>`).join("")}</div><p id="document-dialog-error" class="event-error" role="alert" tabindex="-1" hidden></p><footer class="document-review-footer"><p>Les PDF restent dans ta bibliothèque.<br/><span>Tu pourras reprendre cette revue plus tard.</span></p><div><button type="button" class="secondary-button" data-action="document-dialog-close">Plus tard</button><button id="document-import-events" type="submit" class="primary-button">Ajouter ${count} événement${count > 1 ? "s" : ""} ${icon("check")}</button></div></footer></form></dialog>`;
}
export function deleteDocumentDialog(document, count) {
  return `<dialog class="app-dialog document-delete-dialog" aria-labelledby="document-delete-title"><header class="dialog-heading"><h2 id="document-delete-title">Supprimer ce PDF?</h2><button class="icon-button" data-action="document-dialog-close" aria-label="Fermer">${icon("close")}</button></header><div class="delete-document-file">${icon("document")}<strong>${esc(document.name)}</strong></div><p class="dialog-description">Le PDF et ses propositions seront supprimés de ta bibliothèque.${count ? ` Les ${eventCount(count)} déjà ajouté${count > 1 ? "s" : ""} resteront au calendrier, avec une indication que le document a été supprimé.` : ""}</p><p id="document-dialog-error" class="event-error" role="alert" tabindex="-1" hidden></p><div class="dialog-actions"><button class="secondary-button" data-action="document-dialog-close">Garder le PDF</button><button class="danger-button" data-action="document-delete-confirm">Supprimer le PDF</button></div></dialog>`;
}
